:15px;min-height:188px;background:rgba(255,255,255,.92);border:1px solid rgba(226,232,240,.95);border-radius:26px;padding:18px;box-shadow:0 16px 44px rgba(15,23,42,.06);overflow:hidden;transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease}.medal-card:hover{transform:translateY(-3px);box-shadow:0 24px 60px rgba(15,23,42,.1);border-color:color-mix(in srgb,var(--medal-color,#f59e0b) 38%,#e2e8f0)}.medal-card:before{content:"";position:absolute;inset:0 0 auto 0;height:4px;background:linear-gradient(90deg,var(--medal-color,#f59e0b),rgba(255,255,255,0))}.medal-card.owned{background:linear-gradient(135deg,#fff,rgba(255,250,235,.96))}.medal-icon-wrap,.medal-detail-icon{flex:0 0 auto;width:92px;height:92px;border-radius:26px;background:radial-gradient(circle at 30% 20%,#fff,rgba(255,255,255,.55)),linear-gradient(135deg,color-mix(in srgb,var(--medal-color,#f59e0b) 18%,#fff),#f8fafc);border:1px solid color-mix(in srgb,var(--medal-color,#f59e0b) 28%,#e2e8f0);display:grid;place-items:center;box-shadow:inset 0 1px 0 rgba(255,255,255,.8),0 16px 34px rgba(15,23,42,.08)}.medal-icon-wrap img,.medal-detail-icon img{width:78px;height:78px;object-fit:contain;display:block}.medal-card-body{min-width:0;display:flex;flex-direction:column;gap:9px;flex:1}.medal-card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.medal-card h2{font-size:19px;line-height:1.25;margin:0;color:#0f172a}.medal-card h2 a{color:inherit}.medal-card-top span{white-space:nowrap;font-size:12px;font-weight:900;color:var(--medal-color,#f59e0b);background:color-mix(in srgb,var(--medal-color,#f59e0b) 12%,#fff);border:1px solid color-mix(in srgb,var(--medal-color,#f59e0b) 22%,#e2e8f0);border-radius:999px;padding:5px 9px}.medal-card p{margin:0;color:#64748b;line-height:1.62;font-size:14px}.medal-rule{font-size:12px;color:#334155;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:12px;padding:7px 9px}.medal-progress{height:8px;border-radius:999px;background:#e2e8f0;overflow:hidden}.medal-progress i{display:block;height:100%;background:linear-gradient(90deg,var(--medal-color,#f59e0b),#facc15)}.medal-card-foot{margin-top:auto;display:flex;justify-content:space-between;align-items:center;gap:10px;color:#94a3b8}.medal-card-foot a,.medal-equip-form button{border:0;border-radius:999px;background:#0f172a;color:#fff;padding:9px 13px;font-weight:900;cursor:pointer}.medal-detail-hero{justify-content:flex-start}.medal-detail-icon{width:132px;height:132px;border-radius:34px;position:relative;z-index:1}.medal-detail-icon img{width:112px;height:112px}.medal-detail-meta{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.medal-detail-meta span{padding:8px 11px;border-radius:999px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.22);font-weight:800}.medal-panel{max-width:1180px;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-radius:26px;padding:18px;box-shadow:0 16px 44px rgba(15,23,42,.055)}.medal-panel h2{margin:0 0 14px;color:#0f172a;font-size:20px}.medal-users{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.medal-user{display:flex;align-items:center;gap:10px;border:1px solid #e2e8f0;border-radius:16px;padding:10px;color:#0f172a;background:#f8fafc}.medal-user img{width:38px;height:38px;border-radius:50%;object-fit:cover}.medal-user span{font-weight:900;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.medal-user small{margin-left:auto;color:#94a3b8}.medal-empty{grid-column:1/-1;background:#fff;border:1px dashed #cbd5e1;border-radius:22px;padding:26px;text-align:center;color:#64748b;font-weight:800}.medal-alert{max-width:1180px;margin:0 auto 12px;border-radius:16px;padding:12px 14px;font-weight:800}.medal-alert.error{background:#fef2f2;color:#991b1b;border:1px solid #fecaca}.clay-user-badges{display:inline-flex;align-items:center;gap:5px;flex-wrap:wrap}.clay-user-medal{display:inline-flex;align-items:center;gap:4px;max-width:128px;padding:3px 7px 3px 4px;border-radius:999px;background:color-mix(in srgb,var(--medal-color,#f59e0b) 12%,#fff);border:1px solid color-mix(in srgb,var(--medal-color,#f59e0b) 25%,#e2e8f0);color:#334155;font-size:12px;font-weight:900;line-height:1.2;vertical-align:middle}.clay-user-medal img,.clay-user-medal svg{width:18px;height:18px;object-fit:contain;flex:0 0 auto}.clay-user-medal span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}@media(max-width:980px){.medal-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.medal-users{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:640px){.medal-page{padding:12px 12px 96px}.medal-hero,.medal-detail-hero{border-radius:24px;padding:22px;align-items:flex-start;flex-direction:column}.medal-hero h1,.medal-detail-hero h1{font-size:28px}.medal-grid{grid-template-columns:1fr}.medal-card{border-radius:22px;padding:14px}.medal-icon-wrap{width:74px;height:74px;border-radius:20px}.medal-icon-wrap img{width:62px;height:62px}.medal-users{grid-template-columns:1fr}.medal-detail-icon{width:112px;height:112px}.medal-detail-icon img{width:96px;height:96px}}.medal-toast{position:fixed;left:50%;bottom:112px;transform:translateX(-50%);z-index:90;min-width:220px;max-width:92vw;padding:14px 22px;border-radius:999px;background:rgba(15,23,42,.92);color:#fff;font-size:14px;font-weight:800;text-align:center;opacity:0;pointer-events:none;transition:opacity .18s ease}.medal-toast.show{opacity:1;pointer-events:auto}</style><?= function_exists('clay_medal_display_style_tag') ? clay_medal_display_style_tag() : '' ?></head><body><?php require dirname(__DIR__) . '/layouts/topbar.php'; ?>
<main class="medal-page medal-mine-page">
  <section class="medal-hero">
    <div><span class="medal-kicker">My Honors</span><h1>我的勋章</h1><p>管理已获得勋章的佩戴状态。个人资料与帖子作者信息会展示已佩戴勋章。</p></div>
    <a class="medal-hero-action" href="/index.php?path=medals">勋章中心</a>
  </section>
  <?php if ($error): ?><div class="medal-alert error"><?= htmlspecialchars($error) ?></div><?php endif; ?>
  <section class="medal-grid mine">
    <?php foreach ($medals as $m): ?>
      <article class="medal-card owned level-<?= htmlspecialchars((string)$m['level']) ?>" style="--medal-color:<?= htmlspecialchars((string)$m['color']) ?>">
        <a class="medal-icon-wrap" href="/index.php?path=medal&id=<?= (int)$m['badge_id'] ?>"><?php if(!empty($m['icon'])): ?><img src="<?= htmlspecialchars((string)$m['icon']) ?>" alt="" loading="lazy"><?php endif; ?></a>
        <div class="medal-card-body">
          <div class="medal-card-top"><h2><?= htmlspecialchars((string)$m['name']) ?></h2><span><?= !empty($m['is_equipped'])?'佩戴中':'未佩戴' ?></span></div>
          <p><?= htmlspecialchars((string)($m['description'] ?? '')) ?></p>
          <small>获得时间：<?= htmlspecialchars((string)($m['granted_at'] ?? '')) ?></small>
          <form method="post" action="/index.php?path=me/medals" class="medal-equip-form">
