<div class="medal-toast" id="medalToast"></div>
<script>
(function(){
  var toast=document.getElementById('medalToast');
  var msgs={equipped:'已装备',unequipped:'已卸下'};
  var m=(/[?&]msg=([^&]+)/.exec(location.search)||[])[1];
  if(m&&msgs[m]){toast.textContent=msgs[m];toast.classList.add('show');setTimeout(function(){toast.classList.remove('show');},2000);}
})();
</script>

